/// Returns : 32-bit device ID code as specified in LPC2300 data sheet ///

UInt32 iap_rd_device_id (void)
{
  UInt32 results [2]            ;
  UInt32 command [5] = { 54 }   ;

  iap_execute (command,results) ;

  return results [1]            ;
}

